// aim.cpp
// Builds with: cl /std:c++17 /O2 /W3 aim.cpp /link user32.lib gdi32.lib
// Exported logic:
//   ProjectHeadToScreen()  – world-to-screen for a single entity head bone
//   SmoothDelta()          – exponential smoothing clamped to a 240 px cone
//   AimTick()              – iterates entity list, picks best target, returns delta

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cstring>
#include <cstdint>
#include <optional>
#include <array>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

struct Matrix4x4
{
    float m[4][4];
};

static inline Vec2 operator-(Vec2 a, Vec2 b) noexcept { return { a.x - b.x, a.y - b.y }; }
static inline float Dot2(Vec2 a, Vec2 b)     noexcept { return a.x * b.x + a.y * b.y; }
static inline float Len2(Vec2 v)             noexcept { return std::sqrt(Dot2(v, v)); }

// ---------------------------------------------------------------------------
// Viewport / view-matrix state  (caller fills these before first tick)
// ---------------------------------------------------------------------------

struct ViewState
{
    Matrix4x4 viewProj;   // column-major MVP (view * projection)
    float     screenW;    // e.g. 2560.0f
    float     screenH;    // e.g. 1440.0f
};

// ---------------------------------------------------------------------------
// Entity representation
// ---------------------------------------------------------------------------

static constexpr int kMaxEntities = 64;

struct Entity
{
    Vec3     headWorld;   // world-space head bone position
    bool     valid;       // alive & enemy
    float    health;
};

// ---------------------------------------------------------------------------
// ProjectHeadToScreen
//
// Multiplies the world-space head position through viewProj and returns the
// 2-D screen coordinate.  Returns std::nullopt when the point is behind the
// near plane (w <= 0).
// ---------------------------------------------------------------------------

std::optional<Vec2> ProjectHeadToScreen(const Vec3& world,
                                         const ViewState& vs) noexcept
{
    const auto& m = vs.viewProj.m;

    float x = m[0][0] * world.x + m[1][0] * world.y + m[2][0] * world.z + m[3][0];
    float y = m[0][1] * world.x + m[1][1] * world.y + m[2][1] * world.z + m[3][1];
    float w = m[0][3] * world.x + m[1][3] * world.y + m[2][3] * world.z + m[3][3];

    if (w <= 0.0f)
        return std::nullopt;

    float invW = 1.0f / w;
    float ndcX =  x * invW;   // [-1, 1]
    float ndcY = -y * invW;   // [-1, 1], flip Y for screen space

    Vec2 screen;
    screen.x = (ndcX + 1.0f) * 0.5f * vs.screenW;
    screen.y = (ndcY + 1.0f) * 0.5f * vs.screenH;
    return screen;
}

// ---------------------------------------------------------------------------
// SmoothDelta
//
// Applies exponential smoothing between the previous accumulated delta and
// the raw delta toward the target.  Any raw delta whose magnitude exceeds
// kConePx pixels is discarded (outside the acquisition cone) and the
// smoothed value decays toward zero instead.
//
//   alpha      – smoothing factor in (0, 1]; 1.0 = no smoothing
//   kConePx    – cone radius in screen pixels (240 by spec)
// ---------------------------------------------------------------------------

static constexpr float kConePx = 240.0f;

Vec2 SmoothDelta(Vec2 rawDelta,
                 Vec2 prevSmoothed,
                 float alpha) noexcept
{
    float dist = Len2(rawDelta);
    if (dist > kConePx)
    {
        // Target is outside cone – decay toward (0, 0)
        return { prevSmoothed.x * (1.0f - alpha),
                 prevSmoothed.y * (1.0f - alpha) };
    }

    Vec2 result;
    result.x = prevSmoothed.x + alpha * (rawDelta.x - prevSmoothed.x);
    result.y = prevSmoothed.y + alpha * (rawDelta.y - prevSmoothed.y);
    return result;
}

// ---------------------------------------------------------------------------
// AimTick
//
// Iterates the entity array, projects each valid enemy head to screen,
// selects the one closest to the crosshair, and returns the smoothed pixel
// delta from screen-centre.
//
// Returns (0, 0) when no valid target is found inside the cone.
// ---------------------------------------------------------------------------

Vec2 AimTick(const Entity    entities[kMaxEntities],
             const ViewState& vs,
             Vec2             prevSmoothed,
             float            alpha) noexcept
{
    Vec2  screenCentre { vs.screenW * 0.5f, vs.screenH * 0.5f };
    float bestDistSq   = kConePx * kConePx;   // hard gate: 240 px
    Vec2  bestRaw      { 0.0f, 0.0f };
    bool  found        = false;

    for (int i = 0; i < kMaxEntities; ++i)
    {
        const Entity& ent = entities[i];
        if (!ent.valid || ent.health <= 0.0f)
            continue;

        auto projected = ProjectHeadToScreen(ent.headWorld, vs);
        if (!projected)
            continue;

        Vec2 delta  = *projected - screenCentre;
        float dSq   = Dot2(delta, delta);

        if (dSq < bestDistSq)
        {
            bestDistSq = dSq;
            bestRaw    = delta;
            found      = true;
        }
    }

    if (!found)
    {
        // Decay smoothed state when no target is in cone
        return SmoothDelta({ 0.0f, 0.0f }, prevSmoothed, alpha);
    }

    return SmoothDelta(bestRaw, prevSmoothed, alpha);
}

// ---------------------------------------------------------------------------
// Smoke-test entry point (compiled only when AIMTEST is defined)
// ---------------------------------------------------------------------------

#ifdef AIMTEST

#include <cstdio>

int main()
{
    // Build an identity-ish ViewProj that maps a point in front of the camera
    // straight to the centre of a 1920x1080 viewport.
    ViewState vs {};
    vs.screenW = 1920.0f;
    vs.screenH = 1080.0f;

    // Simple orthographic-like projection for smoke purposes:
    //   NDC = (world.x / 500, world.y / 500, z, 1)
    vs.viewProj.m[0][0] = 1.0f / 500.0f;
    vs.viewProj.m[1][1] = 1.0f / 500.0f;
    vs.viewProj.m[2][2] = 1.0f;
    vs.viewProj.m[3][3] = 1.0f;

    // Entity whose head is exactly at world origin → should project to screen centre.
    Entity entities[kMaxEntities] {};
    entities[0].valid     = true;
    entities[0].health    = 100.0f;
    entities[0].headWorld = { 0.0f, 0.0f, 0.0f };

    // Off-centre target: 100 px right of centre
    entities[1].valid     = true;
    entities[1].health    = 80.0f;
    entities[1].headWorld = { 100.0f * 500.0f / (vs.screenW * 0.5f), 0.0f, 0.0f };

    Vec2 smoothed { 0.0f, 0.0f };
    constexpr float kAlpha = 0.3f;

    for (int tick = 0; tick < 5; ++tick)
    {
        smoothed = AimTick(entities, vs, smoothed, kAlpha);
        std::printf("tick %d  smoothed=(%.3f, %.3f)\n", tick, smoothed.x, smoothed.y);
    }

    // Verify ProjectHeadToScreen returns nullopt for w<=0
    ViewState vsNeg = vs;
    vsNeg.viewProj.m[3][3] = -1.0f;   // force w negative
    auto behind = ProjectHeadToScreen({ 0.0f, 0.0f, 0.0f }, vsNeg);
    std::printf("behind-plane result is %s\n", behind ? "VISIBLE (unexpected)" : "culled (OK)");

    return 0;
}

#endif // AIMTEST
